schema:
syntax = "proto3";
package stargate.v1;

message StargateTelemetry {
  string printer_id = 1;
  int64 ts_us = 2;
  uint32 layer = 3;
  string print_job_id = 4;
  double x = 5;
  double y = 6;
  double z = 7;
  double melt_pool_temp_c = 8;
  double deposition_rate_kg_hr = 9;
  double arm_vibration_g = 10;
  optional double laser_power_w = 11;
}
